import { readFileSync, writeFileSync, renameSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const file = process.env.NOTES_FILE || 'data/notes.json';

function load() {
  try {
    const data = JSON.parse(readFileSync(file, 'utf8'));
    return Array.isArray(data) ? data : [];
  } catch (e) {
    if (e.code === 'ENOENT') return [];
    throw new Error(`Could not read notes file ${file}: ${e.message}`);
  }
}

function save() {
  mkdirSync(dirname(file), { recursive: true });
  const tmp = `${file}.tmp`;
  writeFileSync(tmp, JSON.stringify(notes, null, 2));
  renameSync(tmp, file); // atomic replace, avoids a half-written file
}

const notes = load();
let nextId = notes.reduce((max, n) => Math.max(max, n.id), 0) + 1;

export const listNotes = () => notes;
export function addNote(text) { const n = { id: nextId++, text, createdAt: new Date().toISOString() }; notes.push(n); save(); return n; }
export function deleteNote(id) { const i = notes.findIndex((n) => n.id === id); if (i < 0) return false; notes.splice(i, 1); save(); return true; }
EOF
